'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {signedCents} from '@/lib/service-forward';
import {readHandoffCreateCancellation,readHandoffOptions,prepareHandoffCreate,handoffCreateArgs,readHandoffCreateReceipt,readHandoffCreateStatus,loadHandoffCreate,saveHandoffCreate,clearHandoffCreate,type HandoffScope,type HandoffCreate} from '@/lib/cashier-handoff';
export function CashierHandoffCreate({scope,session,onSaved}:{scope:HandoffScope;session:string;onSaved:()=>void}){
 const [cancelConfirmed,setCancelConfirmed]=useState(false),[options,setOptions]=useState<ReturnType<typeof readHandoffOptions>|null>(null),[pending,setPending]=useState<HandoffCreate|null>(null),[search,setSearch]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState('');const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadHandoffCreate(sessionStorage,scope,session))}catch(e){setError(e instanceof Error?e.message:'Unable to recover handoff.')}return()=>{alive.current=false}},[scope.tenant,scope.property,scope.actor,session]);
 async function identify(){const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this drawer.');}
 async function load(){if(lock.current)return;lock.current=true;setBusy(true);setError('');setOptions(null);try{await identify();if(!alive.current)return;const value=await hotelRpc('cashier_handoff_options',{p_tenant:scope.tenant,p_property:scope.property,p_session:session,p_search:search});const parsed=readHandoffOptions(value,scope,session,search);await identify();if(alive.current)setOptions(parsed)}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Unable to load receivers.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function save(request:HandoffCreate,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;saveHandoffCreate(sessionStorage,request);setPending(request);const value=await hotelRpc(status?'cashier_handoff_status':'create_cashier_handoff',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:request.request,p_kind:'create'}:handoffCreateArgs(request));await identify();if(!alive.current)return;if(status){if(!readHandoffCreateStatus(value,request)){setMessage('No saved handoff found. Retry the original request.');return}}else readHandoffCreateReceipt(value,request);clearHandoffCreate(sessionStorage,request);setPending(null);setOptions(null);setMessage('Handoff recorded. The receiver must acknowledge the cash.');onSaved()}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Handoff interrupted. Check the saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const value=await hotelRpc('cancel_cashier_handoff_creation_request',{p_tenant:scope.tenant,p_property:scope.property,p_request:request.request,p_confirmed:true});await identify();if(!alive.current)return;readHandoffCreateCancellation(value,request);clearHandoffCreate(sessionStorage,request);setPending(null);setOptions(null);setCancelConfirmed(false);setMessage('Unrecorded handoff cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm the result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 return <section className="card"><h3>Hand off drawer cash</h3>{pending?<><p>Pending amount: {usd(Number(pending.amount))}. {pending.reason}</p><button disabled={busy} onClick={()=>void save(pending)}>Retry cash handoff</button><button disabled={busy} onClick={()=>void save(pending,true)}>Check cash handoff</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this request only if no handoff was recorded.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel unrecorded handoff</button></>:<><form onSubmit={e=>{e.preventDefault();void load()}}><label className="field">Search receiver by email<input value={search} maxLength={200} disabled={busy} onChange={e=>{setSearch(e.target.value);setOptions(null)}}/></label><button disabled={busy}>Find handoff receivers</button></form>{options&&<><p>Available counted cash: {usd(Number(options.available))}</p>{options.refineSearch&&<p>More receivers match. Refine the email search to find yours.</p>}{options.paused?<p>Cashier activity is paused.</p>:<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);void save(prepareHandoffCreate(scope,session,crypto.randomUUID(),options,String(f.get('receiver')),String(signedCents(f.get('amount'))),String(f.get('reason')).trim()))}catch(e){setError(e instanceof Error?e.message:'Review handoff details.')}}}><fieldset disabled={busy||options.available==='0'||options.receivers.length===0}><label className="field">Cash receiver<select name="receiver" required>{options.receivers.map(r=><option key={r.id} value={r.id}>{r.label}</option>)}</select></label><label className="field">Handoff amount (USD)<input name="amount" inputMode="decimal" required/></label><label className="field">Handoff explanation<input name="reason" required minLength={4} maxLength={500}/></label><label><input type="checkbox" required/>I confirm the receiver and amount. The receiver will confirm receipt separately.</label><button>Record cash handoff</button></fieldset></form>}</>}</>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>
}